class Solution:
    def minimumPenalty(self, n: int, start: int, requests: list[int]) -> int:
        pts = sorted(set(requests) | {start})
        k = len(pts)
        s = pts.index(start)
        INF = float('inf')
        dp = [[[INF] * 2 for _ in range(k)] for _ in range(k)]
        dp[s][s][0] = dp[s][s][1] = 0
        for length in range(2, k + 1):
            for i in range(k - length + 1):
                j = i + length - 1
                rem = k - length
                best_l = INF
                if dp[i + 1][j][0] < INF:
                    best_l = min(best_l, dp[i + 1][j][0] + (pts[i + 1] - pts[i]) * rem)
                if dp[i + 1][j][1] < INF:
                    best_l = min(best_l, dp[i + 1][j][1] + (pts[j] - pts[i]) * rem)
                dp[i][j][0] = best_l
                best_r = INF
                if dp[i][j - 1][1] < INF:
                    best_r = min(best_r, dp[i][j - 1][1] + (pts[j] - pts[j - 1]) * rem)
                if dp[i][j - 1][0] < INF:
                    best_r = min(best_r, dp[i][j - 1][0] + (pts[j] - pts[i]) * rem)
                dp[i][j][1] = best_r
        return min(dp[0][k - 1])

