class Solution {
public:
    long long minimumPenalty(int n, int start, vector<int>& requests) {
        vector<long long> pts;
        for (int r : requests) pts.push_back(r);
        pts.push_back(start);
        sort(pts.begin(), pts.end());
        pts.erase(unique(pts.begin(), pts.end()), pts.end());
        int k = pts.size(), s = lower_bound(pts.begin(), pts.end(), (long long)start) - pts.begin();
        const long long INF = LLONG_MAX / 2;
        vector<vector<array<long long,2>>> dp(k, vector<array<long long,2>>(k, {INF, INF}));
        dp[s][s][0] = dp[s][s][1] = 0;
        for (int len = 2; len <= k; ++len)
            for (int i = 0; i + len <= k; ++i) {
                int j = i + len - 1;
                long long rem = k - len;
                long long bl = INF;
                if (dp[i+1][j][0] < INF) bl = min(bl, dp[i+1][j][0] + (pts[i+1]-pts[i])*rem);
                if (dp[i+1][j][1] < INF) bl = min(bl, dp[i+1][j][1] + (pts[j]-pts[i])*rem);
                dp[i][j][0] = bl;
                long long br = INF;
                if (dp[i][j-1][1] < INF) br = min(br, dp[i][j-1][1] + (pts[j]-pts[j-1])*rem);
                if (dp[i][j-1][0] < INF) br = min(br, dp[i][j-1][0] + (pts[j]-pts[i])*rem);
                dp[i][j][1] = br;
            }
        return min(dp[0][k-1][0], dp[0][k-1][1]);
    }
};

