class Solution {
    public long minimumPenalty(int n, int start, int[] requests) {
        java.util.TreeSet<Long> set = new java.util.TreeSet<>();
        for (int r : requests) set.add((long) r);
        set.add((long) start);
        long[] pts = set.stream().mapToLong(Long::longValue).toArray();
        int k = pts.length, s = 0;
        while (pts[s] != start) s++;
        final long INF = Long.MAX_VALUE / 2;
        long[][][] dp = new long[k][k][2];
        for (long[][] a : dp) for (long[] b : a) { b[0] = INF; b[1] = INF; }
        dp[s][s][0] = dp[s][s][1] = 0;
        for (int len = 2; len <= k; len++)
            for (int i = 0; i + len <= k; i++) {
                int j = i + len - 1;
                long rem = k - len;
                long bl = INF;
                if (dp[i+1][j][0] < INF) bl = Math.min(bl, dp[i+1][j][0] + (pts[i+1]-pts[i])*rem);
                if (dp[i+1][j][1] < INF) bl = Math.min(bl, dp[i+1][j][1] + (pts[j]-pts[i])*rem);
                dp[i][j][0] = bl;
                long br = INF;
                if (dp[i][j-1][1] < INF) br = Math.min(br, dp[i][j-1][1] + (pts[j]-pts[j-1])*rem);
                if (dp[i][j-1][0] < INF) br = Math.min(br, dp[i][j-1][0] + (pts[j]-pts[i])*rem);
                dp[i][j][1] = br;
            }
        return Math.min(dp[0][k-1][0], dp[0][k-1][1]);
    }
}

