var minimumPenalty = function(n, start, requests) {
    const pts = [...new Set([...requests, start])].sort((a, b) => a - b);
    const k = pts.length, s = pts.indexOf(start);
    const INF = Infinity;
    const dp = Array.from({length: k}, () => Array.from({length: k}, () => [INF, INF]));
    dp[s][s][0] = dp[s][s][1] = 0;
    for (let len = 2; len <= k; len++)
        for (let i = 0; i + len <= k; i++) {
            const j = i + len - 1, rem = k - len;
            let bl = INF;
            if (dp[i+1][j][0] < INF) bl = Math.min(bl, dp[i+1][j][0] + (pts[i+1]-pts[i])*rem);
            if (dp[i+1][j][1] < INF) bl = Math.min(bl, dp[i+1][j][1] + (pts[j]-pts[i])*rem);
            dp[i][j][0] = bl;
            let br = INF;
            if (dp[i][j-1][1] < INF) br = Math.min(br, dp[i][j-1][1] + (pts[j]-pts[j-1])*rem);
            if (dp[i][j-1][0] < INF) br = Math.min(br, dp[i][j-1][0] + (pts[j]-pts[i])*rem);
            dp[i][j][1] = br;
        }
    return Math.min(dp[0][k-1][0], dp[0][k-1][1]);
};

