class Solution:
    def minimumPenalty(self, n: int, start: int, requests: list[int]) -> int:
        ans = sum(abs(r - start) for r in requests)
        left = [r for r in requests if r < start]
        right = [r for r in requests if r > start]
        if left and right:
            L = start - min(left)
            R = max(right) - start
            ans += min(2 * L * len(right), 2 * R * len(left))
        return ans

