class Solution {
public:
    long long minimumPenalty(int n, int start, vector<int>& requests) {
        long long ans = 0;
        int mnL = INT_MAX, mxR = INT_MIN;
        long long cl = 0, cr = 0;
        for (int r : requests) {
            ans += abs((long long)r - start);
            if (r < start) { mnL = min(mnL, r); cl++; }
            else if (r > start) { mxR = max(mxR, r); cr++; }
        }
        if (cl && cr)
            ans += min(2LL * (start - mnL) * cr, 2LL * (mxR - start) * cl);
        return ans;
    }
};

